/// A block's default-state collision shape; `None` for `Unknown`.
pub fn collision(block: BlockKind) -> Option<Collision> {
    if let BlockKind::Unknown(_) = block {
        return None;
    }
    usize::try_from(block.id())
        .ok()
        .and_then(|i| COLLISION.get(i))
        .copied()
}
